function today(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const v=Object.fromEntries(p.map(x=>[x.type,x.value]));return `${v.year}-${v.month}-${v.day}`}
function parseDate(s){return new Date(`${s}T12:00:00`)}
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function shift(s,n){const d=parseDate(s);d.setDate(d.getDate()+n);return iso(d)}
function labelDate(s){return parseDate(s).toLocaleDateString('en-US',{month:'short',day:'numeric'})}
