function key(d){return `${state.profile?.birthday||'explore'}:${d.id}`}
function record(d){return state.claims[key(d)]||{status:'todo',value:0,spent:0}}
function win(d){if(state.verified[key(d)])return state.verified[key(d)];if(!state.profile||!d.confirmed)return null;const b=state.profile.birthday;if(d.reward_window==='month'){const dt=parseDate(b);return {start:iso(new Date(dt.getFullYear(),dt.getMonth(),1,12)),end:iso(new Date(dt.getFullYear(),dt.getMonth()+1,0,12))}}if(d.id==='chickfila')return {start:parseDate(b).getDay()===0?shift(b,-1):b,end:shift(b,29)};if(d.reward_window==='week')return {start:shift(b,-7),end:shift(b,7)};return {start:b,end:b}}
function eligibility(d){if(!state.profile)return d.confirmed?'Check requirements':'Confirm first';const w=win(d);if(w?.end<today())return 'Expired';if(state.verified[key(d)])return 'Reward confirmed';if(!d.confirmed)return 'Confirm first';if(d.lead_days>0&&!state.members[key(d)]&&shift(state.profile.birthday,-d.lead_days)<today())return 'Signup deadline passed';return d.lead_days>0?'Sign up ahead':'Eligible to plan'}
function mapQuery(d){const personal=state.verified[key(d)]?.branch,saved=state.branches?.[key(d)],branch=coverage(d);return personal||saved?.address||(saved?`${d.business} ${saved.area}, TX`:null)||branch?.address||`${d.business} ${branch?currentArea():(d.city==='National'?currentArea():d.city)}, TX`}
