function locationLabel(d){const saved=state.branches?.[key(d)];if(saved&&saved.area!==currentArea())return `Saved branch · ${saved.area}`;return coverage(d)?`Branch verified · ${currentArea()}`:state.verified[key(d)]?.branch?'Branch checked by you':'Local branch not verified'}
function dealCountText(list){return `${list.length} deals · ${locationMode==='verified'?'verified branches in '+currentArea():'all programs, check local coverage'}`}
function locationControls(){return `<div class="location-controls"><label>Area<select id="browseArea">${metroAreas.map(a=>`<option value="${a}" ${currentArea()===a?'selected':''}>${a}</option>`).join('')}</select></label><label>Location coverage<select id="locationMode"><option value="verified" ${locationMode==='verified'?'selected':''}>Verified in this area</option><option value="all" ${locationMode==='all'?'selected':''}>All researched programs</option></select></label><p>Branch coverage is still growing. A verified branch does not guarantee reward participation.</p></div>`}
function rewardReady(d){if(!state.profile)return false;const p=state.profile,e=eligibility(d);return p.categories.includes(d.category)&&(p.cost!=='free'||d.purchase==='no')&&!['Expired','Signup deadline passed','Confirm first'].includes(e)}
function active(d){return rewardReady(d)&&(inCity(d)||!!state.verified[key(d)]?.branch)}
