function ensureSelections(){if(!state.selected)state.selected=Object.fromEntries(planned().map(d=>[key(d),true]))}
function filterDeals(list,f,q=''){const term=q.toLowerCase().trim();return list.filter(d=>{const w=win(d);return (!term||(d.business+' '+d.offer).toLowerCase().includes(term))&&(f.category==='All'||d.category===f.category)&&(f.purchase==='all'||d.purchase===f.purchase)&&(f.signup==='all'||(f.signup==='required'?!!d.enroll_url:!d.enroll_url))&&(f.scope==='all'||(f.scope==='national'?d.city==='National':d.city!=='National'))&&(f.window==='all'||d.reward_window===f.window)&&(f.availability==='all'||(f.availability==='ready'?active(d):f.availability==='confirm'?eligibility(d)==='Confirm first'||eligibility(d)==='Signup deadline passed':active(d)&&w&&w.start<=today()&&w.end>=today()))})}
function sortDeals(list,order){const name=(a,b)=>a.business.localeCompare(b.business);return [...list].sort((a,b)=>order==='name-desc'?name(b,a):order==='category'?a.category.localeCompare(b.category)||name(a,b):order==='free'?(a.purchase==='no'?0:1)-(b.purchase==='no'?0:1)||name(a,b):order==='expiry'?(win(a)?.end||'9999').localeCompare(win(b)?.end||'9999')||name(a,b):order==='window'?['day','week','month','custom'].indexOf(a.reward_window)-['day','week','month','custom'].indexOf(b.reward_window)||name(a,b):order==='date'?scheduleDate(a,0).localeCompare(scheduleDate(b,0))||name(a,b):name(a,b))}
function selectOptions(options,value){return options.map(([v,label])=>`<option value="${v}" ${v===value?'selected':''}>${label}</option>`).join('')}
function dealControls(context){const itinerary=context==='itinerary',f=itinerary?itineraryFilters:browseFilters,order=itinerary?itinerarySort:browseSort,q=itinerary?itinerarySearch:search,count=Object.entries(f).filter(([k,v])=>v!=='all'&&v!=='All').length+(itinerary?0:filter!=='All'?1:0);return `<div class="deal-controls"><label class="search-label">${itinerary?'Search saved deals':'Search deals'}<input id="${itinerary?'itinerarySearch':'dealSearch'}" type="search" placeholder="Search a business or treat" value="${esc(q)}"></label><label class="sort-label">Sort by<select data-sort="${context}">${selectOptions([...(itinerary?[['date','Planned day']]:[]),['name','Business A–Z'],['name-desc','Business Z–A'],['category','Category'],['free','No purchase first'],...(state.profile?[['expiry','Soonest expiry']]:[]),...(!itinerary?[['window','Reward window']]:[])],order)}</select></label></div><details class="deal-filters" ${count?'open':''}><summary>Filters${count?` (${count})`:''}</summary><div class="filter-fields">${itinerary?`<label>Category<select data-deal-filter="category" data-context="${context}">${selectOptions([['All','All categories'],...cats.map(c=>[c,c])],f.category)}</select></label>`:''}<label>Purchase<select data-deal-filter="purchase" data-context="${context}">${selectOptions([['all','All purchase rules'],['no','No purchase required'],['yes','Purchase required'],['unknown','Purchase rules unclear']],f.purchase)}</select></label><label>Rewards signup<select data-deal-filter="signup" data-context="${context}">${selectOptions([['all','All signup rules'],['required','Rewards signup required'],['none','No rewards signup stated']],f.signup)}</select></label><label>Location<select data-deal-filter="scope" data-context="${context}">${selectOptions([['all','Local + national'],['local','Houston-area deals'],['national','National programs']],f.scope)}</select></label><label>Reward window<select data-deal-filter="window" data-context="${context}">${selectOptions([['all','Any reward window'],['day','Birthday day'],['week','Birthday week'],['month','Birthday month'],['custom','Other / check dates']],f.window)}</select></label>${state.profile?`<label>Availability<select data-deal-filter="availability" data-context="${context}">${selectOptions([['all','Any availability'],...(!itinerary?[['ready','Ready to add'],['confirm','Needs confirmation']]:[]),['today','Redeemable today']],f.availability)}</select></label>`:''}</div><button class="textbtn" data-reset-filters="${context}">Reset filters & search</button></details>`}
function itineraryList(){return sortDeals(filterDeals(planned().filter(d=>record(d).status!=='claimed'),itineraryFilters,itinerarySearch),itinerarySort)}
function itineraryResults(){const items=itineraryList(),total=planned().filter(d=>record(d).status!=='claimed').length;let html;if(itinerarySort==='date'){const groups={};items.forEach(d=>(groups[scheduleDate(d,0)]||=[]).push(d));html=Object.keys(groups).sort().map(date=>`<section class="day"><div class="dayhead"><div class="datebox">${parseDate(date).getDate()}</div><div><h3>${esc(longDate(date))}${date===state.profile.birthday?' 🎂':''}</h3></div></div><div class="cards">${groups[date].map(d=>card(d)).join('')}</div></section>`).join('')}else html=`<div class="cards">${items.map(d=>card(d)).join('')}</div>`;return `<p class="result-count" aria-live="polite">${items.length} of ${total} saved stops shown</p>${items.length?html:total?'<div class="empty"><h3>No saved deals match.</h3><p>Your saved stops are still in your itinerary.</p><button class="outline" data-reset-filters="itinerary">Reset filters & search</button></div>':`<div class="empty"><h3>${totals().count?'All caught up!':'Pick a few birthday treats.'}</h3><p>Browse the deals and add your favorites here.</p><button class="primary" data-section="all">Browse deals →</button></div>`}`}
function updateDealResults(context){if(context==='itinerary'){document.querySelector('#itineraryResults').innerHTML=itineraryResults();return}const list=catalogList();document.querySelector('#dealGrid').innerHTML=list.map(d=>card(d)).join('')||'<div class="empty">No matches. Try another search or reset your filters.</div>';document.querySelector('#dealCount').textContent=dealCountText(list)}
function catalogList(){let list=locationMode==='verified'?offers.filter(inCity):[...offers];if(state.profile)list=list.filter(d=>state.profile.categories.includes(d.category)&&(state.profile.cost!=='free'||d.purchase==='no'));if(filter!=='All')list=list.filter(d=>d.category===filter);return sortDeals(filterDeals(list,browseFilters,search),browseSort)}
function schedule(){const total=planned().filter(d=>record(d).status!=='claimed').length;return `<div class="toolbar"><div><h2>My itinerary</h2><p class="subtle">${total} saved stop${total===1?'':'s'}. Saved stops stay here when you change areas. Open Details to check the branch or change a day.</p></div>${total?'<button class="outline small" id="emailPlan">Email my itinerary ↗</button>':''}</div>${dealControls('itinerary')}<div id="itineraryResults">${itineraryResults()}</div>`}
function signup(){const items=offers.filter(d=>inCity(d)&&(d.lead_days>0||!d.confirmed)&&record(d).status!=='skip');return `<span class="eyebrow">A LITTLE PREP GOES A LONG WAY</span><h2>Before you head out</h2><div class="note">Only offers with confirmed eligibility enter your schedule. Unknown signup timing stays here until you have the actual reward. Joining a program yourself is required; we never enroll you.</div><div class="cards">${items.map(d=>`${card(d)}${d.lead_days>0?`<div class="card"><b>${esc(d.business)} signup deadline: ${labelDate(shift(state.profile.birthday,-d.lead_days))}</b><p class="subtle">The rule is 24 hours, so sign up earlier than this date if possible.</p><label><input type="checkbox" data-member="${d.id}" ${state.members[key(d)]?'checked':''}> I was already enrolled and entered my birthday in time</label></div>`:''}`).join('')}</div>`}
function runs(){const groups={};planned().filter(d=>record(d).status==='todo').forEach(d=>{const area=state.branches?.[key(d)]?.area||(coverage(d)?currentArea():'Your checked branches');(groups[area]||=[]).push(d)});return `<span class="eyebrow">OUT OF THE GROUP CHAT, INTO THE WORLD</span><h2>Little birthday runs</h2><p class="subtle">Neighborhood groupings, not calculated routes. Directions open in Maps; we don’t guess driving time or store hours.</p>${Object.entries(groups).map(([area,items])=>`<div class="run"><span class="pill green">${items.length} available stop${items.length===1?'':'s'}</span><h3>${esc(area)}</h3><p>${items.map(d=>esc(d.business)).join(' → ')}</p><p class="tiny">Individual reward windows still apply. Add your preferred branch before planning national-chain stops.</p><div class="actions">${items.map(d=>`<a class="outline small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(mapQuery(d))}" target="_blank" rel="noopener">${esc(d.business)} ↗</a>`).join('')}</div></div>`).join('')||'<div class="empty">No remaining stops in your current preferences.</div>'}`}
function recap(){const t=totals(),claimed=offers.filter(d=>record(d).status==='claimed');return `<div class="toolbar"><div><h2>${t.count} treat${t.count===1?'':'s'} claimed 🎉</h2><p class="subtle">Your birthday wins, all together.</p></div>${t.count?'<button class="outline small" id="shareHaul">Share my haul ↗</button>':''}</div>${t.count?`<details class="value-summary"><summary>Track your savings (optional)</summary><p>$${t.value.toFixed(2)} recorded value · $${t.spent.toFixed(2)} spent · $${(t.value-t.spent).toFixed(2)} net</p><p class="subtle">Open a claimed deal’s Details to add its value.</p></details>`:''}<div class="cards">${claimed.map(d=>card(d)).join('')||'<div class="empty">Claim a treat from your itinerary and it will appear here.</div>'}</div>`}
function explorer(){const list=catalogList();return `<div class="toolbar"><div><h2>${view==='plan'?'Pick your birthday treats':'Browse birthday deals'}</h2><p class="subtle">Open a deal for its rules.${state.profile?' Add the ones you want to your itinerary.':''}</p></div></div>${locationControls()}${dealControls('browse')}<div class="chips">${['All',...cats].map(c=>`<button data-filter="${c}" class="${filter===c?'active':''}" aria-pressed="${filter===c}">${c}</button>`).join('')}</div><p id="dealCount" class="result-count" aria-live="polite">${esc(dealCountText(list))}</p><div class="cards" id="dealGrid">${list.map(d=>card(d)).join('')||'<div class="empty">No matches. Try another search or reset your filters.</div>'}</div>`}
function plan(){const p=state.profile,t=totals(),count=planned().filter(d=>record(d).status!=='claimed').length;const labels={all:'All deals',schedule:`My itinerary (${count})`,recap:`Claimed (${t.count})`};return `<section class="pagehead"><div><span class="eyebrow">${esc(p.city)} · ${labelDate(p.birthday)}</span><h1>${p.name&&p.name!=='My' ?esc(p.name)+'’s birthday treats':'Your birthday treats'}</h1></div><button class="textbtn" data-view="edit">Edit birthday</button></section><div class="plan-navigation"><div class="plan-tabs">${Object.entries(labels).map(([id,l])=>`<button data-section="${id}" class="${section===id?'active':''}" aria-pressed="${section===id}">${l}</button>`).join('')}</div><details class="plan-tools"><summary>Save & share</summary><div><button id="emailPlan">Email itinerary</button><button id="printPlan">Print</button><button id="exportCalendar">Save calendar</button><button data-account="open">Save to my account</button><button id="backup">Download backup</button><button id="restore">Restore backup</button></div></details></div><section class="plan-content">${section==='schedule'?schedule():section==='recap'?recap():explorer()}</section>${community()}`}
function about(){return `<section style="max-width:750px;margin:40px auto"><span class="eyebrow">A LITTLE CLARITY</span><h1 style="font-size:52px">Good treats.<br>Clear expectations.</h1><h3>How this works</h3><p>Enter your name, birthday month and day, plan year, city, and preferences. No birth year, full address, or account is required. Your birthday plan and checkoffs save in this browser. Use “Save a backup” to keep a copy.</p><h3>Houston area first. Room to grow.</h3><p>This growing catalog includes national programs and Houston/Texas leads, with uncertain rewards clearly marked. A listing does not guarantee a participating branch nearby. The starting-area dropdown covers Houston and selected suburbs. The default view includes only programs with verified branch evidence for your selected area. Coverage is incomplete. Use “All researched programs” to see the rest, clearly labeled when a local branch is unverified. A store’s existence does not guarantee reward participation. Saved stops remain available when you change areas. We don’t yet calculate distances, driving times, hours, or optimized routes.</p><h3>Free means what it says.</h3><p>The $0 filter includes only offers with an explicit no-purchase rule. Dining perks and unclear purchase terms show only when you include other deals. Some offers require a previous purchase, paid tier, or advance enrollment; they are labeled and do not enter a $0-only itinerary.</p><h3>Not sure? We won’t guess.</h3><p>Signup timing that isn’t published is marked “Confirm first.” It enters your schedule only after you confirm you have the reward and enter its dates. The offer’s own terms always control.</p><h3>Share a deal, help a birthday.</h3><p>Community and business submissions go into a private review queue. A listing is free to submit, with no paid feature requirement. Approval requires checking the source and redemption details. Your contact email is never part of a public listing.</p><h3>Your information</h3><p>Birthday Treat Trail is free. You are not enrolled in Tiny Site Studios marketing or merchant rewards by making a plan. Merchant reward signups are separate and subject to each business’s terms. An optional account saves your plan across devices. The itinerary email is a one-time message you explicitly request. The address is sent to our transactional email service for delivery, not added to a marketing list.</p><p>Without an account, plans stay on your device. With an account, the plan is also saved privately online. Deal submissions, including any optional contact email, are sent to Tiny Site Studios for review and stored securely. We don’t enroll you in loyalty programs or add you to marketing lists. Google Fonts loads the typefaces, and Maps or merchant links open their services when clicked.</p><p>For corrections or submission removal: <a href="mailto:caitlin@tinysitestudios.com">caitlin@tinysitestudios.com</a>.</p><button class="outline" id="clearData">Clear my saved birthday plan</button></section>`}
function render(){app.innerHTML=view==='home'?home():view==='edit'?builder():view==='about'?about():view==='deals'?`<section class="browse-banner"><p>No account needed. Pick your favorites after entering your birthday.</p><button class="primary small" data-view="${state.profile?'plan':'home'}">${state.profile?'My deals':'Enter my birthday'} →</button></section>${explorer()}${community()}`:state.profile?plan():home()}
async function rest(path,options={}){const response=await fetch(`${BASE}/rest/v1/${path}`,{...options,headers:{apikey:KEY,Authorization:`Bearer ${KEY}`,'Content-Type':'application/json',...options.headers}});if(!response.ok)throw Error('Could not connect. Please try again; your form is still here.');return response.status===204||response.headers.get('content-length')==='0'?null:response.json().catch(()=>null)}
async function loadOffers(){try{const list=await rest('birthday_offers?active=eq.true&select=*');offers=[...seed,...researchCatalog,...(list||[]).map(d=>({...d,confirmed:true,area:d.city}))];if(view!=='home'&&view!=='edit')render();else{const intro=document.querySelector('.welcome p');if(intro)intro.textContent=`Your birthday deserves a few extra stops. Discover treats, pick your favorites, and make a little day of it.`}}catch{toast('Showing the researched catalog. Community listings could not load.')}}
function submitForm(kind,deal){if(kind==='community'){open(`<h2>Suggest a birthday deal</h2><p class="subtle">Just tell us what you found. We’ll verify the offer and fill in the details before it appears here.</p><form id="submissionForm"><input type="hidden" name="kind" value="community"><div class="fields"><label class="full">Business name<input name="business" required maxlength="120" placeholder="Where is the deal?"></label><label class="full">What’s the birthday deal?<textarea name="offer" required maxlength="1000" placeholder="A free drink, dessert, birthday discount… whatever you know."></textarea></label><label class="full">City or location<input name="city" required maxlength="120" value="${esc(state.profile?.city||'Houston')}" placeholder="City, or National for a chain-wide offer"></label></div><details class="suggestion-extras"><summary>Add a link or contact email (optional)</summary><label>Link to the deal<input name="source" type="url" maxlength="1000" placeholder="https://..."></label><label>Your email<input name="contact" type="email" maxlength="254" placeholder="Only if you’d like us to follow up"></label></details><label class="hide" aria-hidden="true">Leave blank<input name="fax" tabindex="-1" autocomplete="off"></label><p class="tiny">Sent privately to Tiny Site Studios for review. No account or marketing signup.</p><p id="formError" class="error" role="alert"></p><button type="submit" class="primary">Send suggestion →</button></form>`);return}open(`<span class="eyebrow">${kind==='business'?'BUSINESSES ARE PART OF THE PARTY':kind==='report'?'KEEP THE GOOD INFORMATION GOOD':'A GOOD FIND IS BETTER SHARED'}</span><h2>${kind==='business'?'Add your birthday deal.':kind==='report'?'Something changed?':'Share a birthday freebie.'}</h2><p class="subtle">${kind==='business'?'Submit for a free listing—no paid placement needed. We review the terms before publishing.':'Submissions are reviewed before appearing in anyone’s adventure.'}</p><form id="submissionForm"><input type="hidden" name="kind" value="${kind}"><div class="fields"><label>Business name<input name="business" required maxlength="120" value="${esc(deal?.business||'')}"></label><label>City<input name="city" required maxlength="120" value="${esc(state.profile?.city||'Houston')}"></label><label class="full">${kind==='report'?'What changed?':'What is the birthday offer?'}<textarea name="offer" required maxlength="1000" placeholder="A free cupcake on your birthday...">${kind==='report'?'':esc(deal?.offer||'')}</textarea></label><label class="full">Address / participating locations<input name="address" maxlength="240" value="${esc(deal?.address||'')}" placeholder="Street address, locations, or online"></label><label>Category<select name="category">${cats.map(c=>`<option ${deal?.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Birthday window<select name="reward_window"><option value="month">Birthday month</option><option value="week">Birthday week</option><option value="day">Birthday day</option><option value="custom">Another window / not sure</option></select></label><label class="full">Exact redemption timing<textarea name="timing" required maxlength="1000" placeholder="Example: birthday day only; 7 days before through 7 days after. Not sure? Say so."></textarea></label><label>Purchase needed?<select name="purchase"><option value="no">No purchase required</option><option value="yes">Yes—purchase / dine-in required</option><option value="unknown" selected>Not sure</option></select></label><label>Contact email ${kind==='business'?'(required)':'(optional)'}<input name="contact" type="email" maxlength="254" ${kind==='business'?'required':''}></label><label class="full">Signup rules / restrictions<textarea name="signup" required maxlength="1000" placeholder="Membership? Signup deadline? Minimum spend? ID needed? Or no signup needed."></textarea></label><label class="full">Direct rewards signup link (if enrollment is required)<input name="enroll_url" type="url" maxlength="1000" placeholder="https://..."></label><label class="full">Link to the offer or business page<input name="source" type="url" required maxlength="1000" placeholder="https://..." value="${esc(deal?.source||'')}"></label><label class="hide" aria-hidden="true">Leave blank<input name="fax" tabindex="-1" autocomplete="off"></label></div><label style="margin:20px 0;display:flex;gap:10px;align-items:flex-start"><input type="checkbox" required> I believe these details are accurate and agree to send them to Tiny Site Studios for review. My email will stay private.</label><p id="formError" class="error" role="alert"></p><button type="submit" class="primary">${kind==='report'?'Send correction':'Submit for review'} →</button></form>`)}
function submissionPayload(v){const community=v.kind==='community',text=k=>String(v[k]||'').trim();return {kind:v.kind,business:text('business'),offer:text('offer'),city:text('city'),address:text('address'),category:community?'Unknown':v.category,reward_window:community?'custom':v.reward_window,timing:community?'Not provided — verify before publishing':text('timing'),purchase:community?'unknown':v.purchase,signup:community?'Not provided — verify before publishing':text('signup'),source:text('source'),enroll_url:text('enroll_url'),contact:text('contact')}}
function claimForm(d){const r=record(d);open(`<span class="eyebrow">ANOTHER BIRTHDAY WIN</span><h2>You got the ${esc(d.business)} treat! 🎉</h2><p class="subtle">Add the value from a menu or receipt if you know it. Leave zero when you don’t—no made-up totals.</p><form id="claimForm" data-id="${d.id}"><div class="fields"><label>Item value ($)<input name="value" type="number" min="0" max="10000" step="0.01" value="${Number(r.value||0)}" required></label><label>Spent to unlock it ($)<input name="spent" type="number" min="0" max="10000" step="0.01" value="${Number(r.spent||0)}" required></label></div><button type="submit" class="primary" style="margin-top:20px">Add to my birthday haul ✓</button></form>`)}
function confirmForm(d){const w=win(d);open(`<h2>Have the reward in hand?</h2><p class="subtle">Only confirm when you actually have a valid coupon or the business confirmed you qualify. This does not enroll you.</p><form id="confirmForm" data-id="${d.id}"><div class="fields"><label>Valid from<input name="start" type="date" required value="${w?.start||state.profile.birthday}"></label><label>Expires<input name="end" type="date" required value="${w?.end||state.profile.birthday}"></label></div>${!coverage(d)?`<label style="margin-top:16px">Checked branch / address<input name="branch" required maxlength="240" placeholder="Business location you will visit" value="${esc(state.verified[key(d)]?.branch||'')}"></label>`:''}<p id="confirmError" class="error" role="alert"></p><label style="margin:20px 0"><input type="checkbox" required> I have checked the reward, dates, and that my chosen branch accepts it.</label><button class="primary">Add the confirmed reward</button></form>`)}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}
function calendar(){const items=planned().filter(d=>record(d).status==='todo'),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const clean=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const events=items.map((d,i)=>{const date=scheduleDate(d,i);return ['BEGIN:VEVENT',`UID:ba-${d.id}-${state.profile.birthday}@tinysitestudios.com`,`DTSTAMP:${stamp}`,`DTSTART;VALUE=DATE:${date.replace(/-/g,'')}`,`DTEND;VALUE=DATE:${shift(date,1).replace(/-/g,'')}`,`SUMMARY:${clean(`Birthday treat: ${d.business}`)}`,`DESCRIPTION:${clean(d.offer+'\n'+d.signup+'\n'+d.notes+'\n'+d.source)}`,`LOCATION:${clean(mapQuery(d))}`,'END:VEVENT'].join('\r\n')});download('birthday-treat-trail.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Tiny Site Studios//Birthday Treat Trail//EN','CALSCALE:GREGORIAN',...events,'END:VCALENDAR'].join('\r\n'),'text/calendar')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=offers.find(x=>x.id===Object.values(b.dataset)[0]);if(b.dataset.resetFilters){if(b.dataset.resetFilters==='itinerary'){itineraryFilters=defaultFilters();itinerarySearch=''}else{browseFilters=defaultFilters();search='';filter='All'}render()}if(b.dataset.details)dealDetails(offers.find(x=>x.id===b.dataset.details));if(b.dataset.startPlan){close();view='home';render();window.scrollTo(0,0)}if(b.dataset.add){if(!active(d)){dealDetails(d);return}ensureSelections();const branch=coverage(d);if(branch){state.branches??={};state.branches[key(d)]={area:currentArea(),address:branch.address,url:branch.url}}state.selected[key(d)]=true;delete state.claims[key(d)];save();close();render();toast('Added to your itinerary.')}if(b.dataset.remove){ensureSelections();delete state.selected[key(d)];save();close();render();toast('Removed from your itinerary.')}if(b.dataset.view){view=b.dataset.view;render();window.scrollTo(0,0)}if(b.dataset.section){section=b.dataset.section;view='plan';render()}if(b.dataset.scroll)document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'});if(b.dataset.submit)submitForm(b.dataset.submit);if(b.dataset.report)submitForm('report',d);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.value)claimForm(d);if(b.dataset.claim){state.claims[key(d)]={status:'claimed',value:0,spent:0};save();close();render();toast('Treat claimed. Happy birthday!')}if(b.dataset.confirm)confirmForm(d);if(b.dataset.skip){state.claims[key(d)]={status:'skip',value:0,spent:0};save();render();toast('Skipped. You can bring it back from Explore deals.')}if(b.dataset.undo){delete state.claims[key(d)];save();render()}if(b.dataset.reschedule){const w=win(d);open(`<h2>Make it fit your day.</h2><form id="moveForm" data-id="${d.id}"><label>${esc(d.business)} · ${labelDate(w.start)}–${labelDate(w.end)}<input name="date" type="date" required min="${w.start>today()?w.start:today()}" max="${w.end}" value="${scheduleDate(d,0)}"></label><p class="tiny">Check store hours. Chick-fil-A is closed Sundays.</p><p id="moveError" class="error"></p><button class="primary" style="margin-top:15px">Move this stop</button></form>`)}if(b.id==='closeModal')close();if(b.id==='printPlan')window.print();if(b.id==='emailPlan')open('<span class="eyebrow">A COPY FOR YOUR INBOX</span><h2>Email your itinerary.</h2><p class="subtle">Enter an address and we’ll send your confirmed itinerary once. We do not add you to marketing or create an account.</p><form id="emailPlanForm"><label>Email address<input name="email" type="email" required autocomplete="email"></label><button class="primary" style="margin-top:16px">Send my itinerary ↗</button></form>');if(b.id==='backup')download('my-birthday-treat-trail.json',JSON.stringify(state,null,2),'application/json');if(b.id==='restore')open('<h2>Bring your adventure back.</h2><p class="subtle">Choose the JSON backup from Birthday Treat Trail. This replaces your current plan and syncs to your account if signed in.</p><form id="restoreForm"><label>Birthday Treat Trail backup<input type="file" name="backup" accept="application/json,.json" required></label><p id="restoreError" class="error"></p><button class="primary" style="margin-top:15px">Restore my adventure</button></form>');if(b.id==='exportCalendar')calendar();if(b.id==='pickNext'){const list=planned().filter(d=>record(d).status==='todo'&&win(d).start<=today()&&win(d).end>=today());if(!list.length){toast('No confirmed offers redeemable today. Your itinerary shows what’s next.');return}const next=list[Math.floor(Math.random()*list.length)];open(`<span class="eyebrow">YOUR NEXT LITTLE ADVENTURE</span>${card(next)}`)}if(b.id==='shareHaul'){const t=totals(),text=`I collected ${t.count} birthday treats worth $${t.value.toFixed(2)} and spent $${t.spent.toFixed(2)}. My Birthday Treat Trail: https://tinysitestudios.com/birthday-adventure/`;if(navigator.share)navigator.share({title:'My Birthday Treat Trail',text}).catch(()=>{});else if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>toast('Your haul is copied. Go make someone jealous.')).catch(()=>toast(text));else toast(text)}if(b.id==='clearData'){if(confirm('Clear this device’s saved birthday plan and haul?')){state={profile:null,claims:{},bookings:{},verified:{},members:{}};save();view='home';render();toast('Saved plan cleared.')}}});
document.addEventListener('change',e=>{if(e.target.id==='browseArea'){browseArea=e.target.value;if(state.profile){state.profile.city=browseArea;state.profile.area='Other city';save()}render();return}if(e.target.id==='locationMode'){locationMode=e.target.value;render();return}if(e.target.dataset.dealFilter){const f=e.target.dataset.context==='itinerary'?itineraryFilters:browseFilters;f[e.target.dataset.dealFilter]=e.target.value;const context=e.target.dataset.context,name=e.target.dataset.dealFilter;render();document.querySelector(`[data-deal-filter="${name}"][data-context="${context}"]`)?.focus();return}if(e.target.dataset.sort){if(e.target.dataset.sort==='itinerary')itinerarySort=e.target.value;else browseSort=e.target.value;updateDealResults(e.target.dataset.sort);return}if(e.target.dataset.member){const d=offers.find(d=>d.id===e.target.dataset.member);state.members[key(d)]=e.target.checked;save();render()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['profileForm','submissionForm','claimForm','confirmForm','moveForm','restoreForm','emailPlanForm'].includes(form.id))return;e.preventDefault();if(form.id==='emailPlanForm'){const address=new FormData(form).get('email');const items=planned().filter(d=>record(d).status!=='claimed').map((d,i)=>({date:scheduleDate(d,i),business:d.business,offer:d.offer,signup:d.signup,source:d.source,...(d.enroll_url?{enroll:d.enroll_url}:{})}));const btn=form.querySelector('button');btn.disabled=true;btn.textContent='Sending…';try{if(!items.length)throw Error('There are no confirmed stops to email yet. Explore deals and confirm your rewards first.');const response=await fetch('https://seating-studio-email.vercel.app/api/birthday-itinerary',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:state.profile.name,email:address,birthday:state.profile.birthday,city:state.profile.city,items,website:''})});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Email could not be sent.');close();toast('Your itinerary email is on its way. Check your inbox and spam folder.')}catch(err){form.querySelector('p.error')?.remove();const error=document.createElement('p');error.className='error';error.textContent=err.message;form.insertBefore(error,btn);btn.disabled=false;btn.textContent='Send my itinerary ↗'}return}if(form.id==='restoreForm'){try{const file=new FormData(form).get('backup');if(!file||file.size>1000000)throw Error('Choose a Birthday Treat Trail backup under 1 MB.');const restored=JSON.parse(await file.text()),p=restored.profile;if(!p||typeof p.city!=='string'||typeof p.name!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(p.birthday)||!Array.isArray(p.categories)||!p.categories.length||p.categories.some(c=>!cats.includes(c)))throw Error('This file does not contain a valid birthday plan.');const maps={};for(const name of ['claims','bookings','verified','members','selected','branches']){if(restored[name]!==undefined){if(!restored[name]||typeof restored[name]!=='object'||Array.isArray(restored[name]))throw Error('This backup contains invalid saved deals.');maps[name]=restored[name]}}if(iso(parseDate(p.birthday))!==p.birthday)throw Error('This backup contains an invalid birthday.');state={profile:p,claims:{},bookings:{},verified:{},members:{},...maps};save();close();view='plan';section='all';render();toast('Your backup is restored.')}catch(err){document.querySelector('#restoreError').textContent=err.message}return}const f=new FormData(form),v=Object.fromEntries(f),d=offers.find(d=>d.id===form.dataset.id);if(form.id==='profileForm'){const date=new Date(Number(v.year),Number(v.month)-1,Number(v.day),12);if(date.getMonth()!==Number(v.month)-1||date.getDate()!==Number(v.day)){toast('Choose a real calendar date.');return}const categories=f.getAll('category');if(!categories.length){toast('Choose at least one kind of treat.');return}const city=v.city.trim().replace(/,\s*(TX|Texas)$/i,'');if(!state.profile)state.selected={};state.profile={name:v.name.trim()||'My',birthday:iso(date),city,area:city.toLowerCase()==='houston'?v.area:'Other city',cost:v.cost,categories};save();view='plan';section='all';filter='All';search='';render();window.scrollTo(0,0);toast('Choose your favorite birthday treats.')}if(form.id==='claimForm'){state.claims[key(d)]={status:'claimed',value:Number(v.value),spent:Number(v.spent)};save();close();render();confetti();toast('A little birthday win, officially collected.')}if(form.id==='confirmForm'){if(!coverage(d)&&!String(v.branch||'').trim()){document.querySelector('#confirmError').textContent='Enter the participating branch you checked.';return}if(v.end<v.start||v.end<today()){document.querySelector('#confirmError').textContent='Enter a valid reward window that has not expired.';return}ensureSelections();state.verified[key(d)]={start:v.start,end:v.end,...(v.branch?{branch:v.branch.trim()}:state.verified[key(d)]?.branch?{branch:state.verified[key(d)].branch}:{})};state.selected[key(d)]=true;delete state.claims[key(d)];save();close();render();toast('Confirmed and added when it matches your filters.')}if(form.id==='moveForm'){if(d.id==='chickfila'&&parseDate(v.date).getDay()===0){document.querySelector('#moveError').textContent='Pick another day—Chick-fil-A is closed Sundays.';return}state.bookings[key(d)]=v.date;save();close();render()}if(form.id==='submissionForm'){if(v.fax)return;const btn=form.querySelector('button[type=submit]'),error=document.querySelector('#formError');if((v.source?safeURL(v.source)==='#':v.kind!=='community')||(v.enroll_url&&safeURL(v.enroll_url)==='#')){error.textContent='Enter valid http or https links.';return}btn.disabled=true;btn.textContent='Sending…';error.textContent='';try{const payload=submissionPayload(v);if(!payload.business||!payload.offer||!payload.city)throw Error('Please enter the business, deal, and city or location.');await rest('birthday_submissions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});modalContent.innerHTML=`<span class="eyebrow">THANK YOU FOR MAKING BIRTHDAYS BETTER</span><h2>It’s in the review queue. ✳</h2><p>Your ${v.kind==='report'?'correction':'deal'} was received. Tiny Site Studios will check the source and terms before publishing. Contact details stay private.</p><button class="primary" id="closeModal">Back to the adventure</button>`}catch(err){error.textContent=err.message;btn.disabled=false;btn.textContent=v.kind==='community'?'Send suggestion →':'Submit for review →'}}});
document.addEventListener('input',e=>{if(e.target.id==='dealSearch'){search=e.target.value;updateDealResults('browse')}else if(e.target.id==='itinerarySearch'){itinerarySearch=e.target.value;updateDealResults('itinerary')}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
render();loadOffers();

